"use client";
/* Plug, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Plug(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("plug"); }, []);
  return React.createElement("piix-pal", { "pal": "plug", ...piixAttrs(props) });
}

export default Plug;
